<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();
$today=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)=CURDATE()")->fetchColumn();
$month=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM sales WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())")->fetchColumn();
$due=(float)$pdo->query("SELECT COALESCE(SUM(balance),0) FROM sales WHERE balance>0")->fetchColumn();
$customers=(int)$pdo->query("SELECT COUNT(*) FROM customers")->fetchColumn();
$active=(int)$pdo->query("SELECT COUNT(*) FROM swim_sessions WHERE status='active'")->fetchColumn();
$stock=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE stock_qty<=low_stock_level AND active=1")->fetchColumn();
$recent=$pdo->query("SELECT s.id,s.invoice_no,s.total,s.payment_method,s.created_at,COALESCE(c.name,'Walk-in customer') customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id ORDER BY s.id DESC LIMIT 6")->fetchAll();
$days=[];$vals=[];for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$days[]=date('D',strtotime($d));$st=$pdo->prepare("SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)=?");$st->execute([$d]);$vals[]=(float)$st->fetchColumn();}
layout_start('Overview','dashboard'); ?>
