<div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><h3>Revenue overview</h3><p class="muted">Last seven days · sales value</p></div><span class="badge">7 DAYS</span></div><div class="chart" id="revenueChart" data-labels="<?=h(json_encode($days))?>" data-values="<?=h(json_encode($vals))?>"><div class="chart-bars"><?php $max=max($vals)?:1;foreach($vals as $i=>$v):?><div class="bar-column"><div class="bar-value"><?=money($v)?></div><div class="bar-track"><div class="bar-fill" style="height:<?=max(3,($v/$max)*100)?>%"></div></div><span><?=$days[$i]?></span></div><?php endforeach;?></div></div></section><section class="panel quick-panel"><div class="panel-head"><div><h3>Quick actions</h3><p class="muted">Common tasks, one click away</p></div></div><div class="quick-links"><a href="pos.php"><span class="quick-icon violet">＋</span><span><b>Create a bill</b><small>Record a retail or pool payment</small></span><i>↗</i></a><a href="swimmers.php"><span class="quick-icon aqua">◷</span><span><b>Start swim session</b><small>Track swimmer time and expiry</small></span><i>↗</i></a><a href="bookings.php"><span class="quick-icon orange">▦</span><span><b>Add booking</b><small>Schedule a pool visit</small></span><i>↗</i></a><a href="inventory.php"><span class="quick-icon green">▤</span><span><b>Manage stock</b><small><?=$stock?> items at low-stock level</small></span><i>↗</i></a></div></section></div>
